function validateReady(){const missing=[];if(window.FightArena?.version!=='0.9.5.7')missing.push('FightArena core');if(!window.FightArenaDailyControls)missing.push('daily');if(!window.FightArenaCampaignV097)missing.push('campaign');if(!window.MultiverseArenaUpdate0973)missing.push('v0.9.7.3');if(!window.MultiverseArenaUpdate0974)missing.push('v0.9.7.4 Hulkbuster');if(!window.MultiverseArenaUpdate09741)missing.push('v0.9.7.4.1 hotfix');if(missing.length){state.status='warning';state.missing=missing}else state.status='ready';setTimeout(brand,400)}window.addEventListener('fightarena-ready',validateReady,{once:true});
